def verify(path, info):
    require(path.stat().st_size == info['bytes'], 'Размер: ' + str(path))
    sha, md5 = hashlib.sha256(), hashlib.md5()
    with path.open('rb') as stream:
        for block in iter(lambda: stream.read(1024**2), b''):
            sha.update(block); md5.update(block)
    require(sha.hexdigest() == info['sha256'], 'SHA256: ' + str(path))
    if 'md5' in info:
        require(md5.hexdigest() == info['md5'], 'MD5: ' + str(path))

for relative, info in files.items():
    target = Path(relative)
    require(not target.is_absolute() and '..' not in target.parts, 'Путь manifest')
    target.parent.mkdir(parents=True, exist_ok=True)
    if not target.exists():
        partial = target.with_name(target.name + '.part')
        require(not partial.exists(), 'Сохранён частичный файл: сначала проверить его отдельно')
        total = 0
        with urlopen(info['url'], timeout=60) as response, partial.open('xb') as stream:
            while block := response.read(1024**2):
                total += len(block)
                require(total <= info['bytes'], 'Размер загрузки превысил manifest')
                stream.write(block)
        verify(partial, info)
        partial.replace(target)
    verify(target, info)
